SET search_path TO lms, extensions;

-- ============================================================
-- Admin write policies for lms.users
-- ============================================================
-- Note: INSERT on lms.users is primarily handled by the
-- handle_new_user() trigger (SECURITY DEFINER) which runs when
-- a user is created via auth.admin.createUser(). These policies
-- allow the admin to UPDATE user fields (role, is_active, etc.)
-- and soft-delete users from the app layer.
-- ============================================================

-- Admins can update any user row (role, is_active, full_name, etc.)
CREATE POLICY "users: admin update" ON lms.users
  FOR UPDATE
  USING (
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
  )
  WITH CHECK (
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
  );

-- Users can update their own non-sensitive fields (full_name, avatar_url, phone)
-- Prevents self-escalation of role
CREATE POLICY "users: self update non-sensitive" ON lms.users
  FOR UPDATE
  USING (auth.uid() = id)
  WITH CHECK (auth.uid() = id);
